            //Internal. Intentionally not documented.
            this._entities = [];

            //Internal. Intentionally not documented.
            this._activeTexture = null;

            //Internal. Intentionally not documented.
            this._tmpVector = new Vec3(0, 0, 0);
            this._tmpColor = new Color(1, 1, 1, 1);

            //Internal. Intentionally not documented.
            this._vboCacheKey = '';
            this._iboCacheKey = '';
